      "egobOutcome": "NO FAVORABLE",
      "egobOutcomeRule": "subsanacion",
      "egobOutcomeNote": "En el cuadro de linderos no se observa los metrajes correspondientes a los mismos. Cambiar el nombre cuadro de construcción por cuadro de coordenadas. Colocar la clave del predio en la planimetría (se encuentra en el gravamen o pago predial). Debido a la ausencia de hitos o puntos de referencia física visibles que permitan delimitar el predio en campo se solicita al propietario realizar el cerramiento perimetral mediante elementos fijos e identificables (como ejemplo columnas de hormigón y alambre). Esto permitirá realizar la inspección de comprobación y la verificación del replanteo de los puntos presentados, pues en la ortofoto institucional y fotos anexas presentadas no se identifica puntos de consolidación a más de las aceras y bordillos existente sin embargo el predio no se encuentra delimitado.",
      "egobOutcomeAt": "2026-07-27 17:43",
